package com.shoply.application.service;
import com.shoply.application.dto.*; import com.shoply.domain.model.*; import com.shoply.domain.repository.*; import java.math.BigDecimal; import java.util.*;
public class OrderService {private final CartRepository carts;private final ProductRepository products;private final OrderRepository orders;public OrderService(CartRepository carts,ProductRepository products,OrderRepository orders){this.carts=carts;this.products=products;this.orders=orders;}public OrderDto place(UUID customerId){Cart cart=carts.findByCustomerId(customerId).orElseThrow(()->new IllegalArgumentException("Your cart is empty"));var items=cart.items().stream().map(item->{var product=products.findById(item.productId()).orElseThrow(()->new NoSuchElementException("Product not found"));return new OrderItem(product.id(),product.name(),product.price(),item.quantity());}).toList();BigDecimal subtotal=items.stream().map(OrderItem::lineTotal).reduce(BigDecimal.ZERO,BigDecimal::add);Order saved=orders.save(new Order(UUID.randomUUID(),customerId,OrderStatus.PLACED,items,subtotal));cart.clear();carts.save(cart);return dto(saved);}public List<OrderDto> history(UUID customerId){return orders.findByCustomerId(customerId).stream().map(this::dto).toList();}public OrderDto get(UUID customerId,UUID id){return dto(orders.findByIdAndCustomerId(id,customerId).orElseThrow(()->new NoSuchElementException("Order not found")));}private OrderDto dto(Order order){return new OrderDto(order.id(),order.status().name(),order.items().stream().map(i->new OrderItemDto(i.productId(),i.productName(),i.unitPrice(),i.quantity())).toList(),order.subtotal());}}
